The following Terraform configuration creates an AWS Elastic Beanstalk application and an Elastic Beanstalk configuration template. It also creates the required IAM service role and EC2 instance profile role that Elastic Beanstalk uses to manage the environment and EC2 instances.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Elastic Beanstalk application template will be created."
  type        = string
  default     = "us-east-1"
}

variable "application_name" {
  description = "Name of the Elastic Beanstalk application."
  type        = string
  default     = "example-elastic-beanstalk-app"
}

variable "configuration_template_name" {
  description = "Name of the Elastic Beanstalk configuration template."
  type        = string
  default     = "example-elastic-beanstalk-template"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack to use for the configuration template."
  type        = string
  default     = "64bit Amazon Linux 202
